<script setup lang="ts">
// AI 审阅流水线五阶段步骤条：摘要 → 标签 → 难度 → 质量 → 建议。
// 数据源为 problem_annotation_call 推导的阶段状态（EnrichStageStep[]），
// 总览「当前活动」面板（size=md）与题目列表行内（size=sm）共用。
import { computed } from "vue";
import { stageText } from "./enrich-common";
import type { EnrichStageStep } from "@/types/problem-enrichment";

const props = defineProps<{
  steps: EnrichStageStep[];
  size?: "sm" | "md"; // sm 列表行内紧凑版 / md 面板版
}>();

// 每阶段的图标字符：✓ 已完成 / ✗ 失败 / ▶ 进行中 / ○ 未开始
const iconOf = (status: string): string => {
  switch (status) {
    case "success":
      return "✓";
    case "fail":
      return "✗";
    case "running":
      return "▶";
    default:
      return "○";
  }
};

// 每阶段的状态类名（配色）
const clsOf = (status: string): string => `step-${status}`;

const doneCount = computed(() => props.steps.filter((s) => s.status === "success").length);
const totalCount = computed(() => props.steps.length);
</script>

<template>
  <span
    class="pipeline-steps"
    :class="size === 'sm' ? 'pipeline-sm' : 'pipeline-md'"
    :title="steps.map((s) => `${stageText[s.stage] || s.stage}:${s.status}`).join(' · ')"
  >
    <span
      v-for="(s, i) in steps"
      :key="s.stage"
      class="pipeline-step"
      :class="clsOf(s.status)"
    >
      <span class="pipeline-dot">{{ iconOf(s.status) }}</span>
      <span v-if="size !== 'sm'" class="pipeline-label">{{ stageText[s.stage] || s.stage }}</span>
      <span v-if="i < steps.length - 1" class="pipeline-line" />
    </span>
    <span v-if="size === 'sm'" class="pipeline-count">{{ doneCount }}/{{ totalCount }}</span>
  </span>
</template>

